/* General table: name, first mask name, eight ability bytes, the division
 * or staff post (role +1e bits 0-2, else division +1c when bit 2 is set) and
 * Rest (nonzero counter) or Hurt (role bit 6). The formatted row is printed
 * as a format string with the visible start and count as its arguments. */
void opeu_tbl_draw_staff(uint8_t ds[65536], HostEvent event, uint16_t scratch,
                         uint8_t column, uint8_t first, uint8_t row,
                         uint8_t last, uint8_t flags) {
  uint8_t    a, b, c;
  TEXT_PTR   d;
  uint8_t    e;
  PERSON_PTR f;
  TEXT_PTR   g;
  WINDOW_PTR h;
  BUFFER(i, 100, 4);
  h = WINDOW;
  COLUMNS(column, c, row, b, a);
  if (flags & 3) {
    FORMAT(i, REQUEST_TEXT(0x7a));
    POSITION(WIN_COLUMN(h) + c + WIN_X(h) - 0x1f, WIN_Y(h) + 1);
    SIDE_COLOR(SIDE);
    PUT_RANGE(i, b, a);
  }
  for (e = first; e <= last; ++e) {
    f = PERSON_AT(e);
    if (flags & 5) {
      POSITION(WIN_X(h) + 3, (e - TOP) * 17 + WIN_Y(h) + 18);
      SIDE_COLOR(LACKS_FLAG(f));
      PRINT(PERSON_NAME, f);
    }
    d = g = PERSON_BLANK;
    if (FIELD(f, 0x1e) & 7)
      d = POST_NAME((FIELD(f, 0x1e) & 7) + 3);
    else if (FIELD(f, 0x1c) & 4)
      d = POST_NAME(FIELD(f, 0x1c) & 3);
    if (COUNTER(f))
      g = PERSON_REST;
    else if (FIELD(f, 0x1e) & 0x40)
      g = PERSON_HURT;
    FORMAT(i, REQUEST_TEXT(0x78), MASK_NAME(FIELD(f, 0x12)), FIELD(f, 0x13),
           FIELD(f, 0x14), FIELD(f, 0x15), FIELD(f, 0x16), FIELD(f, 0x18),
           FIELD(f, 0x19), FIELD(f, 0x1a), FIELD(f, 0x1b), d, g);
    POSITION(WIN_COLUMN(h) + c + WIN_X(h) - 0x1f,
             (e - TOP) * 17 + WIN_Y(h) + 18);
    TEXT_COLOR(7);
    PRINT(i, b, a);
  }
  TEXT_COLOR(7);
}

